function updateRecSim() {
    const a0 = parseInt(document.getElementById('input-rec-start').value, 10);
    document.getElementById('badge-rec-start').innerText = 'a₀ = ' + a0;

    const a1 = 2 * a0 + 5;
    const a2 = 2 * a1 + 5;
    const a3 = 2 * a2 + 5;
    const a4 = 2 * a3 + 5;

    document.getElementById('round-1-val').innerText = a1;
    document.getElementById('round-2-val').innerText = a2;
    document.getElementById('round-3-val').innerText = a3;
    document.getElementById('round-4-val').innerText = a4;

    const pill = document.getElementById('rec-summary-pill');
    if (a3 >= 100) {
        pill.innerHTML = `<i class="fas fa-trophy" style="color:#10b981;"></i> SUCCESS: Round 3 result is ${a3} (≥ 100)! Target achieved.`;
    } else {
        pill.innerHTML = `<i class="fas fa-info-circle" style="color:#60a5fa;"></i> Round 3 result: ${a3} (< 100). Try a larger starting number!`;
    }
}

function setRecStart(val) {
    document.getElementById('input-rec-start').value = val;
    updateRecSim();
}

document.addEventListener('DOMContentLoaded', () => {
    updateRecSim();
});
